          exp(-0.5 * s * log(b2 + t * t)) * K;
        let wf = r * gw[i] * f;
        t3 = t3 + wf;
        a3 = a3 + abs(wf) * ((6.0 + 10.0 * t) +
          (abs(s) * (2.0 + 0.5 * log2(b2 + t * t)) + abs(t * L)));
